// Command gauge is the menubar app: the dashboard runs in-process and
// appears as a popover under the status bar icon.
package main

import (
	"context"
	_ "embed"
	"encoding/json"
	"errors"
	"log"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/abcdlsj/gauge/internal/app"

	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/events"
)

// version is overridden at build time with -ldflags "-X main.version=...".
var version = "dev"

// trayIcon is the 22pt template glyph, generated by scripts/make_icons.py. The
// @2x bitmap is the one handed to Wails: it resizes the NSImage to the status
// bar height itself, so a retina-resolution source is what stays crisp.
//
//go:embed assets/tray-template@2x.png
var trayIcon []byte

// trayClassicIcon is the alternative glyph, picked in Settings → General.
//
//go:embed assets/tray-classic-template@2x.png
var trayClassicIcon []byte

// trayIconFor returns the template glyph for an icon choice.
func trayIconFor(choice string) []byte {
	if app.NormalizeIcon(choice) == app.IconClassic {
		return trayClassicIcon
	}
	return trayIcon
}

func main() {
	logger := log.New(os.Stdout, "", log.LstdFlags|log.Lmsgprefix)

	dir, err := os.UserConfigDir()
	if err != nil {
		logger.Fatalf("config dir: %v", err)
	}
	dataDir := filepath.Join(dir, "Gauge")
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		logger.Fatalf("create %s: %v", dataDir, err)
	}

	ctx := context.Background()
	// tray and ui are created after the app; the hooks only fire once the UI is
	// running, by which time both are set.
	var tray *application.SystemTray
	var ui *application.App
	a, err := app.New(ctx, app.Config{
		DBPath:           filepath.Join(dataDir, "quota.db"),
		KeyPath:          filepath.Join(dataDir, "gauge.key"),
		Logger:           logger,
		Version:          version,
		EnableAutoUpdate: true,
		OnQuit: func() {
			if ui != nil {
				ui.Quit()
			}
		},
		AllowEmbedding: true,
		OnSettingsChange: func(changed map[string]string) {
			if choice, ok := changed[app.IconSetting]; ok && tray != nil {
				tray.SetTemplateIcon(trayIconFor(choice))
			}
		},
	})
	if err != nil {
		logger.Fatalf("start: %v", err)
	}
	snaps, _ := a.Store.Snapshots(ctx)
	keys, _ := a.Store.Keys(ctx)
	freshInstall := len(snaps) == 0 && len(keys) == 0
	a.Engine.Start(ctx)
	a.Updater.Start(ctx)

	// The page reports the height of its painted panel; the shell resizes the
	// window to match so the content hugs all four edges with no dead space.
	// Anything past popoverMaxHeight does not grow the window: the list or the
	// settings form scrolls inside it (see .scroll-wrap in web/popover.css).
	const (
		popoverWidth = 372
		// initialPopoverHeight is only a starting point; the page reports the
		// real height as soon as it has painted.
		initialPopoverHeight = 640
		// popoverMinHeight keeps a nearly empty view (or a page that has not
		// painted yet) from collapsing the popover to a sliver. It matches
		// POPOVER_MIN_HEIGHT in web/popover.js.
		popoverMinHeight = 320
		// popoverMaxHeight is 900pt (the shortest display macOS still supports)
		// less the menu bar (24) and the Dock (96), so the popover always fits
		// between them without clipping its own footer.
		popoverMaxHeight = 780
	)
	var popover *application.WebviewWindow
	fittedHeight := initialPopoverHeight

	fitHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload struct {
			Height int `json:"height"`
		}
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "bad payload", http.StatusBadRequest)
			return
		}
		if payload.Height < popoverMinHeight {
			payload.Height = popoverMinHeight
		}
		if payload.Height > popoverMaxHeight {
			payload.Height = popoverMaxHeight
		}
		if popover != nil && payload.Height != fittedHeight {
			fittedHeight = payload.Height
			resizePopover(popover, popoverWidth, payload.Height)
			logger.Printf("popover content height -> %d", payload.Height)
		}
		w.WriteHeader(http.StatusNoContent)
	})

	// Google redirects back over http, but the popover lives in the app's own
	// scheme. A loopback listener owns the callback path so the consent screen
	// has an address it can reach.
	oauthLn, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		logger.Fatalf("oauth listener: %v", err)
	}
	oauthBase := "http://" + oauthLn.Addr().String()
	const oauthCallbackPath = "/oauth-callback"
	oauthSrv := &http.Server{Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Antigravity's client whitelists the loopback path its own IDE uses
		// (/oauth-callback), so the redirect must hit that one, not /oauth/callback.
		if r.URL.Path != oauthCallbackPath {
			http.NotFound(w, r)
			return
		}
		a.Handler.ServeHTTP(w, r)
	})}
	go func() {
		if err := oauthSrv.Serve(oauthLn); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Printf("oauth listener: %v", err)
		}
	}()

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.URL.Path == "/api/ui/height" && r.Method == http.MethodPost:
			fitHandler.ServeHTTP(w, r)
			return
		case r.URL.Path == "/api/oauth/start":
			// Send the consent screen to the loopback listener; the panel has
			// no page Google could redirect to. back=none keeps the result
			// page from navigating to a web route the app does not serve.
			q := r.URL.Query()
			q.Set("redirect", oauthBase+oauthCallbackPath)
			q.Set("back", "none")
			r.URL.RawQuery = q.Encode()
		}
		a.Handler.ServeHTTP(w, r)
	})

	ui = application.New(application.Options{
		Name: "Gauge",
		Assets: application.AssetOptions{
			Handler:        handler,
			DisableLogging: true,
		},
		Mac: application.MacOptions{
			// Menubar app: no Dock icon, no app switcher entry.
			ActivationPolicy: application.ActivationPolicyAccessory,
		},
	})

	popover = ui.Window.NewWithOptions(application.WebviewWindowOptions{
		Title:           "Gauge",
		Width:           popoverWidth,
		Height:          initialPopoverHeight,
		Frameless:       true,
		Hidden:          true,
		AlwaysOnTop:     true,
		DisableResize:   true,
		HideOnEscape:    true,
		HideOnFocusLost: true,
		URL:             "/popover",
	})

	popover.RegisterHook(events.Common.WindowClosing, func(e *application.WindowEvent) {
		popover.Hide()
		e.Cancel()
	})
	// Refresh any provider whose interval elapsed while the Mac was asleep.
	popover.OnWindowEvent(events.Common.WindowShow, func(*application.WindowEvent) {
		a.Engine.RefreshStale()
	})

	tray = ui.SystemTray.New()
	tray.SetTemplateIcon(trayIconFor(a.Icon(ctx)))
	tray.SetTooltip("Gauge")
	tray.AttachWindow(popover).WindowOffset(6)

	menu := ui.NewMenu()
	menu.Add("Refresh now").OnClick(func(*application.Context) {
		go a.Engine.RefreshAll(ctx)
	})
	menu.AddSeparator()
	menu.Add("Quit").OnClick(func(*application.Context) {
		ui.Quit()
	})
	tray.SetMenu(menu)

	// On a fresh install (no snapshots or saved settings yet), open the popover
	// once the menu bar icon is ready so the user sees where Gauge lives instead
	// of wondering whether launching the app did anything.
	if freshInstall {
		ui.Event.OnApplicationEvent(events.Common.ApplicationStarted, func(*application.ApplicationEvent) {
			go func() {
				time.Sleep(350 * time.Millisecond)
				tray.ShowWindow()
			}()
		})
	}

	ui.OnShutdown(func() {
		_ = oauthSrv.Close()
		_ = a.Close()
	})

	if err := ui.Run(); err != nil {
		logger.Fatalf("run: %v", err)
	}
}
